/**
 * Deployment self-check: a read-only status endpoint for the release script
 * (`GET /api/selfcheck`), guarded by a token that grants nothing else.
 *
 * Why a token and not "loopback only": the platform listens on 127.0.0.1, but a local reverse
 * proxy (for example a tailnet front end) forwards remote requests from 127.0.0.1 too, so the
 * peer address cannot tell the deploy script on this machine from a remote client. The token is
 * generated by the platform at every start and written to `<data-dir>/selfcheck.token` with mode
 * 0600; only processes that can read the data directory (which already holds platform.db) can use
 * it. The platform keeps only its SHA-256 hash in memory and compares in constant time.
 *
 * The report carries runtime versions, migration state and health only: no user ids, names,
 * spaces, sessions, messages or configuration.
 *
 * @module @enkeep/platform-server/server/selfcheck
 */

import { createHash, randomBytes, timingSafeEqual } from 'node:crypto';
import {
  closeSync,
  constants as fsConstants,
  fchmodSync,
  fsyncSync,
  openSync,
  renameSync,
  unlinkSync,
  writeSync,
} from 'node:fs';
import { basename, dirname, join } from 'node:path';
import type { DatabaseSync } from 'node:sqlite';
import type { MigrationDefinition, UserRuntimeUpgradeStatus } from '@enkeep/platform-core';

/** File name of the self-check token inside the platform data directory. */
export const SELF_CHECK_TOKEN_FILE_NAME = 'selfcheck.token';
/** Request header carrying the self-check token. */
export const SELF_CHECK_TOKEN_HEADER = 'x-enkeep-selfcheck-token';
/** Upper bound for an accepted header value (a token is 43 characters). */
const MAX_TOKEN_HEADER_LENGTH = 256;

function sha256(value: string): Buffer {
  return createHash('sha256').update(value, 'utf8').digest();
}

/**
 * Generates a new random self-check token, replaces `filePath` with it atomically (a fresh
 * 0600 file renamed over the old one, so a symlink at the path is replaced, never followed) and
 * returns the token's SHA-256 hash. The token itself is not kept or logged.
 * @param filePath - token file path, normally `<data-dir>/selfcheck.token`.
 */
export function issueSelfCheckToken(filePath: string): Buffer {
  const token = randomBytes(32).toString('base64url');
  const tmpPath = join(dirname(filePath), `.${basename(filePath)}.${process.pid}.${randomBytes(6).toString('hex')}.tmp`);
  const noFollow = fsConstants.O_NOFOLLOW ?? 0;
  const fd = openSync(tmpPath, fsConstants.O_WRONLY | fsConstants.O_CREAT | fsConstants.O_EXCL | noFollow, 0o600);
  try {
    try {
      fchmodSync(fd, 0o600);
      writeSync(fd, `${token}\n`, 0, 'utf8');
      fsyncSync(fd);
    } finally {
      closeSync(fd);
    }
    renameSync(tmpPath, filePath);
  } catch (err) {
    try {
      unlinkSync(tmpPath);
    } catch {}
    throw err;
  }
  return sha256(token);
}

/**
 * True when `headerValue` is the token whose hash is `expectedHash`.
 * @param headerValue - raw header value from the request.
 * @param expectedHash - hash returned by issueSelfCheckToken, or null when no token was issued.
 */
export function verifySelfCheckToken(headerValue: unknown, expectedHash: Buffer | null | undefined): boolean {
  if (!expectedHash || typeof headerValue !== 'string') return false;
  const value = headerValue.trim();
  if (value.length === 0 || value.length > MAX_TOKEN_HEADER_LENGTH) return false;
  return timingSafeEqual(sha256(value), expectedHash);
}

/** Migration state of the platform database against the migrations this build knows. */
export interface SelfCheckMigrationStatus {
  readonly currentVersion: number;
  readonly latestVersion: number;
  readonly pendingVersions: number[];
  readonly upToDate: boolean;
}

/**
 * Reads the applied migration versions (read-only) and compares them with the build's manifest.
 * @param db - platform database.
 * @param manifest - migrations of this build.
 */
export function readMigrationStatus(db: DatabaseSync, manifest: readonly MigrationDefinition[]): SelfCheckMigrationStatus {
  const rows = db.prepare('SELECT version FROM _schema_migrations ORDER BY version ASC').all() as Array<{ version: number }>;
  const applied = new Set(rows.map((r) => Number(r.version)));
  const known = [...new Set(manifest.map((m) => m.version))].sort((a, b) => a - b);
  const pendingVersions = known.filter((v) => !applied.has(v));
  const currentVersion = rows.length > 0 ? Number(rows[rows.length - 1].version) : 0;
  const latestVersion = known.length > 0 ? known[known.length - 1] : 0;
  return { currentVersion, latestVersion, pendingVersions, upToDate: pendingVersions.length === 0 };
}

/** One runtime in the self-check report; deliberately without the user id. */
export interface SelfCheckRuntime {
  readonly mode: 'container' | 'host';
  readonly current: string | null;
  readonly target: string | null;
  readonly isOutdated: boolean;
  readonly isIdle: boolean;
  readonly pendingReason: string | null;
}

/** Strips a runtime upgrade status to what the self-check needs. */
export function toSelfCheckRuntime(st: UserRuntimeUpgradeStatus): SelfCheckRuntime {
  return {
    mode: st.mode,
    current: (st.mode === 'host' ? st.currentDaemonCliPath : st.currentImage) ?? st.currentImage ?? st.currentDaemonCliPath ?? null,
    target: (st.mode === 'host' ? st.targetDaemonCliPath : st.targetImage) ?? st.targetImage ?? st.targetDaemonCliPath ?? null,
    isOutdated: st.isOutdated === true,
    isIdle: st.isIdle === true,
    pendingReason: st.pendingReason ?? null,
  };
}

/** What the platform server gives the HTTP handler for the self-check endpoint. */
export interface SelfCheckSource {
  /** Hash of the current token, or null when none was issued (the endpoint then answers 404). */
  getTokenHash(): Buffer | null;
  /** Migration state of the platform database. */
  getMigrationStatus(): SelfCheckMigrationStatus;
  /** ISO time the platform started serving. */
  getStartedAt(): string | null;
}
